`timescale 1ns/1ps
// Serial reference only; the active v28 module below uses four-byte lanes.
module lz77_rgb_c2h_path_serial #(
    parameter integer IMAGE_WIDTH=1920,IMAGE_HEIGHT=1080,
    parameter integer USE_INPUT_FRAME_ID=0,
    // Formatter emits one 32-bit word per C2H beat.  Split the long image
    // stream into packets below the driver's 256 KiB descriptor window;
    // the RK3576 parser reassembles these fragments before decoding a frame.
    parameter integer PACKET_WORDS=256
)(
    input wire clk,rst_n,input wire i_valid,output wire i_ready,
    input wire [127:0] i_data,input wire i_sof,i_frame_last,input wire [31:0] i_frame_id,
    output wire o_valid,input wire o_ready,output wire [127:0] o_data,
    output wire [15:0] o_keep,output wire o_last,
    output wire [31:0] raw_bytes,compressed_bytes,token_count,frame_count,error_count
);
    wire b_valid,b_ready,b_sof,b_last;wire [7:0] b_data;
    wire e_valid,e_ready,e_match,e_sof,e_last;wire [15:0] e_token;wire [1:0] e_bytes;
    wire [31:0] e_raw,e_comp,e_tokens,e_frames,e_errors;
    wire [31:0] b_errors,f_errors;
    wire [31:0] b_frame_id;
    reg [31:0] sequence_id,frame_id_q;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin sequence_id<=0;frame_id_q<=0;end
        else if(b_valid && b_ready && b_sof) begin
            frame_id_q<=USE_INPUT_FRAME_ID ? b_frame_id : sequence_id;
            sequence_id<=sequence_id+1'b1;
        end
    end
    wire f_valid,f_ready,f_last;wire [31:0] f_data;wire [2:0] f_keep;
    wire p_valid,p_ready,p_last; wire [127:0] p_data; wire [15:0] p_keep;
    rgb128_byte_stream #(.IMAGE_WIDTH(IMAGE_WIDTH),.IMAGE_HEIGHT(IMAGE_HEIGHT)) u_bytes(.clk(clk),.rst_n(rst_n),.i_valid(i_valid),.i_ready(i_ready),.i_data(i_data),.i_sof(i_sof),.i_frame_last(i_frame_last),.i_frame_id(i_frame_id),.o_frame_id(b_frame_id),.o_valid(b_valid),.o_ready(b_ready),.o_data(b_data),.o_sof(b_sof),.o_last(b_last),.error_count(b_errors));
    lz77_repeat_encoder u_encoder(.clk(clk),.rst_n(rst_n),.i_valid(b_valid),.i_ready(b_ready),.i_data(b_data),.i_sof(b_sof),.i_last(b_last),.o_valid(e_valid),.o_ready(e_ready),.o_token(e_token),.o_match(e_match),.o_sof(e_sof),.o_last(e_last),.o_bytes(e_bytes),.raw_byte_count(e_raw),.compressed_byte_count(e_comp),.token_count(e_tokens),.frame_count(e_frames),.error_count(e_errors));
    lz77_frame_formatter #(.IMAGE_WIDTH(IMAGE_WIDTH),.IMAGE_HEIGHT(IMAGE_HEIGHT)) u_formatter(.clk(clk),.rst_n(rst_n),.i_valid(e_valid),.i_ready(e_ready),.i_token(e_token),.i_match(e_match),.i_bytes(e_bytes),.i_sof(e_sof),.i_last(e_last),.i_frame_id(frame_id_q),.o_valid(f_valid),.o_ready(f_ready),.o_data(f_data),.o_keep(f_keep),.o_sof(),.o_last(f_last),.frame_count(frame_count),.error_count(f_errors));
    lz77_c2h_word_packer #(.PACKET_BEATS(PACKET_WORDS/4)) u_word_packer(
        .clk(clk), .rst_n(rst_n), .i_valid(f_valid), .i_ready(f_ready),
        .i_data(f_data), .i_keep(f_keep), .i_last(f_last),
        .o_valid(p_valid), .o_ready(o_ready), .o_data(p_data),
        .o_keep(p_keep), .o_last(p_last)
    );
    assign o_valid=p_valid; assign o_last=p_last; assign o_keep=p_keep; assign o_data=p_data;
    assign raw_bytes=e_raw;assign compressed_bytes=e_comp;assign token_count=e_tokens;
    assign error_count=b_errors+e_errors+f_errors;
endmodule

// BLK1 formatter. A block is buffered until its token payload can be compared
// with the original bytes. kind=0 emits the raw block; kind=1 emits the
// existing token bytes. The outer LZ77 header/footer and IEEE CRC remain.
module lz77_blk1_formatter #(
 parameter integer IMAGE_WIDTH=1920,IMAGE_HEIGHT=1080,BLOCK_BYTES=65536
)(
 input wire clk,rst_n,i_valid,output wire i_ready,
 input wire [95:0] i_data,input wire [3:0] i_bytes,input wire [2:0] i_tokens,
 input wire [15:0] i_raw,input wire [31:0] i_raw_data,
 input wire i_sof,i_last,i_frame_last,input wire [31:0] i_frame_id,
 output reg block_done,
 output reg o_valid,input wire o_ready,output reg [127:0] o_data,
 output reg [4:0] o_bytes,output reg o_last,
 output reg [31:0] compressed_bytes,token_count,frame_count,error_count
);
 localparam integer WORDS=BLOCK_BYTES/16;
 localparam integer AW=WORDS>1 ? $clog2(WORDS):1;
 localparam COLLECT=0,HEADER=1,FLUSH=2,DECIDE=3,BHDR=4,FETCH=5,
            PAYLOAD=6,FOOTER=7,CRC_WORD=8,FAULT=9;
 reg [3:0] state;
 reg frame_active,block_last,comp_overflow,closed;
 reg [31:0] frame_id_q,frame_raw,frame_comp,frame_tokens;
 reg [31:0] block_raw,block_comp,block_tokens,out_pos,chosen_len,remaining;
 reg [4:0] payload_count;
 reg payload_last;
 reg kind;
 reg [31:0] crc_reg;
 reg [127:0] raw_pack,comp_pack;
 reg [4:0] raw_fill,comp_fill;
 reg [AW-1:0] raw_wr,comp_wr;
 // Exactly one full-word write port and one synchronous read port per RAM.
 // No memory array or read register reset: contents become valid through counts.
 (* ram_style="bram(min_area)" *) reg [127:0] raw_mem[0:WORDS-1];
 (* ram_style="bram(min_area)" *) reg [127:0] comp_mem[0:WORDS-1];
 reg [127:0] raw_q,comp_q;
 wire take=i_valid && i_ready;
 wire keep_comp=!comp_overflow && block_comp+i_bytes<=BLOCK_BYTES;
 wire [255:0] raw_join={128'd0,raw_pack} | ({224'd0,i_raw_data} << (8*raw_fill));
 wire [255:0] comp_join={128'd0,comp_pack} | ({160'd0,i_data} << (8*comp_fill));
 wire [5:0] raw_n=raw_fill+6'd4;
 wire [5:0] comp_n=comp_fill+{2'd0,i_bytes};
 wire raw_write=(take && raw_n>=16) || (state==FLUSH && raw_fill!=0);
 wire comp_write=(take && keep_comp && comp_n>=16) ||
                 (state==FLUSH && !comp_overflow && comp_fill!=0);
 wire [127:0] raw_wdata=state==FLUSH ? raw_pack:raw_join[127:0];
 wire [127:0] comp_wdata=state==FLUSH ? comp_pack:comp_join[127:0];
 wire fetch=state==FETCH || (state==PAYLOAD && o_ready && !payload_last);
 wire [31:0] fetch_pos=state==FETCH ? 0:out_pos+payload_count;
 wire [AW-1:0] read_addr=fetch_pos[AW+3:4];
 always @(posedge clk) begin
  if(raw_write) raw_mem[raw_wr]<=raw_wdata;
  if(comp_write) comp_mem[comp_wr]<=comp_wdata;
  if(fetch) begin raw_q<=raw_mem[read_addr];comp_q<=comp_mem[read_addr];end
 end
