 wire e_valid,e_ready,e_sof,e_last;wire [95:0] e_data;
 wire [3:0] e_bytes;wire [2:0] e_tokens;wire [15:0] e_raw;
 wire [31:0] e_id,e_errors,f_errors,e_comp_count,e_tok_count;
 wire [31:0] f_comp_count,f_tok_count;
 reg [31:0] sequence_id;
 wire [31:0] selected_id=USE_INPUT_FRAME_ID ? q_id : sequence_id;
 always @(posedge clk or negedge rst_n)
  if(!rst_n) sequence_id<=0;
  else if(q_valid && q_ready && q_last) sequence_id<=sequence_id+1'b1;
 rgb128_quad_stream #(.IMAGE_WIDTH(IMAGE_WIDTH),.IMAGE_HEIGHT(IMAGE_HEIGHT)) u_quads(
  .clk(clk),.rst_n(rst_n),.i_valid(i_valid),.i_ready(i_ready),.i_data(i_data),
  .i_sof(i_sof),.i_frame_last(i_frame_last),.i_frame_id(i_frame_id),
  .o_valid(q_valid),.o_ready(q_ready),.o_data(q_data),.o_sof(q_sof),.o_last(q_last),
  .o_frame_id(q_id),.error_count(q_errors));
 wire [31:0] e_raw_data;
 wire encoder_ready,block_done;
 reg [31:0] block_input_bytes;
 reg block_wait,frame_end;
 wire block_tail=q_last || block_input_bytes+4>=BLK1_BLOCK_BYTES;
 assign q_ready=encoder_ready && (!BLK1_ENABLE || !block_wait);
 always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin block_input_bytes<=0;block_wait<=0;frame_end<=0;end
  else if(BLK1_ENABLE) begin
   if(block_done) begin block_wait<=0;block_input_bytes<=0;end
   if(q_valid && q_ready) begin
    block_input_bytes<=block_input_bytes+4;
    if(block_tail) begin block_wait<=1;frame_end<=q_last;end
   end
  end
 end
 wire f_valid,f_ready,f_last;wire [127:0] f_data;wire [4:0] f_bytes;
 lz77_quad_encoder u_encoder_raw(
  .clk(clk),.rst_n(rst_n),.i_valid(q_valid && (!BLK1_ENABLE || !block_wait)),.i_ready(encoder_ready),.i_data(q_data),
  .i_sof(BLK1_ENABLE ? block_input_bytes==0:q_sof),
  .i_last(BLK1_ENABLE ? block_tail:q_last),.i_frame_id(selected_id),.o_valid(e_valid),.o_ready(e_ready),
  .o_data(e_data),.o_bytes(e_bytes),.o_tokens(e_tokens),.o_raw(e_raw),.o_raw_data(e_raw_data),
  .o_sof(e_sof),.o_last(e_last),.o_frame_id(e_id),.raw_byte_count(raw_bytes),
  .compressed_byte_count(e_comp_count),.token_count(e_tok_count),.error_count(e_errors));
 generate if(BLK1_ENABLE) begin : gen_blk1
  lz77_blk1_formatter #(.IMAGE_WIDTH(IMAGE_WIDTH),.IMAGE_HEIGHT(IMAGE_HEIGHT),.BLOCK_BYTES(BLK1_BLOCK_BYTES)) u_formatter(
   .clk(clk),.rst_n(rst_n),.i_valid(e_valid),.i_ready(e_ready),.i_data(e_data),
   .i_bytes(e_bytes),.i_tokens(e_tokens),.i_raw(e_raw),.i_raw_data(e_raw_data),
   .i_sof(e_sof),.i_last(e_last),.i_frame_last(e_last && frame_end),.block_done(block_done),.i_frame_id(e_id),.o_valid(f_valid),.o_ready(f_ready),
   .o_data(f_data),.o_bytes(f_bytes),.o_last(f_last),.frame_count(frame_count),.error_count(f_errors),
   .compressed_bytes(f_comp_count),.token_count(f_tok_count));
 end else begin : gen_legacy
  assign block_done=1'b0;
  assign f_comp_count=0;assign f_tok_count=0;
  lz77_quad_formatter #(.IMAGE_WIDTH(IMAGE_WIDTH),.IMAGE_HEIGHT(IMAGE_HEIGHT)) u_formatter(
   .clk(clk),.rst_n(rst_n),.i_valid(e_valid),.i_ready(e_ready),.i_data(e_data),
   .i_bytes(e_bytes),.i_tokens(e_tokens),.i_raw(e_raw),.i_sof(e_sof),.i_last(e_last),
   .i_frame_id(e_id),.o_valid(f_valid),.o_ready(f_ready),.o_data(f_data),
   .o_bytes(f_bytes),.o_last(f_last),.frame_count(frame_count),.error_count(f_errors));
 end endgenerate
 lz77_quad_packer #(.PACKET_BEATS(PACKET_WORDS/4)) u_packer(
  .clk(clk),.rst_n(rst_n),.i_valid(f_valid),.i_ready(f_ready),
  .i_data(f_data),.i_bytes(f_bytes),.i_last(f_last),
  .o_valid(o_valid),.o_ready(o_ready),.o_data(o_data),.o_keep(o_keep),.o_last(o_last));
 assign error_count=q_errors+e_errors+f_errors;
 assign compressed_bytes=BLK1_ENABLE ? f_comp_count:e_comp_count;
 assign token_count=BLK1_ENABLE ? f_tok_count:e_tok_count;
endmodule


// Four source bytes per user clock. The original distance=1 wire tokens are
// retained: literal = 00,value; match = 80|length,01. A repeat may cross any
// source-word boundary. The two pending repeat literals plus four new bytes
// require at most six tokens (12 payload bytes) in one output batch.
module lz77_quad_encoder(
 input wire clk,rst_n,i_valid,output wire i_ready,input wire [31:0] i_data,
 input wire i_sof,i_last,input wire [31:0] i_frame_id,
 output reg o_valid,input wire o_ready,output reg [95:0] o_data,
 output reg [3:0] o_bytes,output reg [2:0] o_tokens,
 output reg [15:0] o_raw,output reg [31:0] o_raw_data,
 output reg o_sof,o_last,output reg [31:0] o_frame_id,
 output reg [31:0] raw_byte_count,compressed_byte_count,token_count,error_count
);
 // Three elastic stages: isolate source word mux, form fixed lane slots,
 // then compact tokens. Four input bytes/clock sustained; no multicycle SDC.
 reg in_valid,in_sof,in_last;
 reg [31:0] in_data,in_id;
 reg lane_valid,lane_sof,lane_last;
 reg [31:0] lane_data,lane_id;
 reg [239:0] lane_slots;
 reg [9:0] lane_counts;
 reg [15:0] lane_raw;
 reg previous_valid;
 reg [7:0] previous;
 reg [6:0] repeats;
 wire output_ready=!o_valid || o_ready;
 wire lane_ready=!lane_valid || output_ready;
 wire input_ready=!in_valid || lane_ready;
 assign i_ready=input_ready;

 // Result: {previous_valid,previous,repeats,token_count,three fixed tokens}.
 // Fixed slots remove variable token shifts from the four-byte state chain.
 function [65:0] step_byte;
  input pv;input [7:0] prev;input [6:0] count;input [7:0] value;
  reg [47:0] slots;reg [1:0] n;reg [6:0] next_count;
  begin
   slots=0;n=0;next_count=0;
   if(!pv) begin slots[15:0]={value,8'd0};n=1;end
   else if(value==prev) begin
    if(count==126) begin slots[15:0]={8'd1,8'hff};n=1;end
    else next_count=count+1'b1;
   end else begin
    case(count)
     0:begin slots[15:0]={value,8'd0};n=1;end
     1:begin slots[31:0]={value,8'd0,prev,8'd0};n=2;end
     2:begin slots={value,8'd0,prev,8'd0,prev,8'd0};n=3;end
     default:begin slots[31:0]={value,8'd0,8'd1,1'b1,count};n=2;end
    endcase
   end
   step_byte={1'b1,value,next_count,n,slots};
  end
 endfunction
 wire [65:0] l0=step_byte(in_sof ? 1'b0:previous_valid,previous,
                         in_sof ? 7'd0:repeats,in_data[7:0]);
 wire [65:0] l1=step_byte(l0[65],l0[64:57],l0[56:50],in_data[15:8]);
 wire [65:0] l2=step_byte(l1[65],l1[64:57],l1[56:50],in_data[23:16]);
 wire [65:0] l3=step_byte(l2[65],l2[64:57],l2[56:50],in_data[31:24]);
 reg [47:0] tail_slots;
 reg [1:0] tail_count;
 always @* begin
  tail_slots=0;tail_count=0;
  if(in_last) begin
   case(l3[56:50])
    0:begin end
    1:begin tail_slots[15:0]={l3[64:57],8'd0};tail_count=1;end
    2:begin tail_slots[31:0]={l3[64:57],8'd0,l3[64:57],8'd0};tail_count=2;end
    default:begin tail_slots[15:0]={8'd1,1'b1,l3[56:50]};tail_count=1;end
   endcase
  end
 end
 // Raw token accounting follows input bytes plus prior pending run minus
 // new pending run. It is independent of token compaction and avoids a
 // second serial chain of variable-width raw-count adders.
 wire [15:0] raw_delta=16'd4+{9'd0,(in_sof ? 7'd0:repeats)}-
                              {9'd0,(in_last ? 7'd0:l3[56:50])};
 reg [95:0] packed_tokens;
 reg [2:0] count0,count1,count2,count3,count4;
 reg [2:0] base1,base2,base3,base4,total_count;
 reg [3:0] diag_bytes;
 integer p,j;
 reg [15:0] token;
 always @* begin
  count0={1'b0,lane_counts[1:0]};count1={1'b0,lane_counts[3:2]};
  count2={1'b0,lane_counts[5:4]};count3={1'b0,lane_counts[7:6]};
  count4={1'b0,lane_counts[9:8]};
  base1=count0;base2=count0+count1;base3=count0+count1+count2;
  base4=count0+count1+count2+count3;total_count=base4+count4;
  packed_tokens=0;diag_bytes=0;token=0;
  for(p=0;p<5;p=p+1) begin
   for(j=0;j<3;j=j+1) begin
    token=lane_slots[p*48+j*16 +:16];
    if(j<lane_counts[p*2 +:2]) begin
     case(p)
      0:packed_tokens[j*16 +:16]=token;
      1:packed_tokens[(base1+j)*16 +:16]=token;
      2:packed_tokens[(base2+j)*16 +:16]=token;
      3:packed_tokens[(base3+j)*16 +:16]=token;
      4:packed_tokens[(base4+j)*16 +:16]=token;
     endcase
     diag_bytes=diag_bytes+(token[7] ? 4'd2:4'd1);
    end
   end
  end
 end
 always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
   in_valid<=0;in_sof<=0;in_last<=0;in_data<=0;in_id<=0;
   lane_valid<=0;lane_sof<=0;lane_last<=0;lane_data<=0;lane_id<=0;
   lane_slots<=0;lane_counts<=0;lane_raw<=0;
   previous_valid<=0;previous<=0;repeats<=0;
   o_valid<=0;o_data<=0;o_bytes<=0;o_tokens<=0;o_raw<=0;o_raw_data<=0;
   o_sof<=0;o_last<=0;o_frame_id<=0;
   raw_byte_count<=0;compressed_byte_count<=0;token_count<=0;error_count<=0;
  end else begin
   if(input_ready) begin
    in_valid<=i_valid;
    if(i_valid) begin
     in_data<=i_data;in_sof<=i_sof;in_last<=i_last;in_id<=i_frame_id;
     raw_byte_count<=raw_byte_count+4;
    end
   end
   if(lane_ready) begin
    lane_valid<=in_valid;
    if(in_valid) begin
     lane_slots<={tail_slots,l3[47:0],l2[47:0],l1[47:0],l0[47:0]};
     lane_counts<={tail_count,l3[49:48],l2[49:48],l1[49:48],l0[49:48]};
     lane_raw<=raw_delta;lane_sof<=in_sof;lane_last<=in_last;
     lane_data<=in_data;lane_id<=in_id;
     if((!previous_valid && !in_sof) || (previous_valid && in_sof))
      error_count<=error_count+1'b1;
     previous_valid<=!in_last;previous<=l3[64:57];
     repeats<=in_last ? 7'd0:l3[56:50];
    end
   end
   if(output_ready) begin
    o_valid<=lane_valid;
    if(lane_valid) begin
     o_data<=packed_tokens;o_bytes<={total_count,1'b0};o_tokens<=total_count;
     o_raw<=lane_raw;o_raw_data<=lane_data;o_sof<=lane_sof;o_last<=lane_last;o_frame_id<=lane_id;
     compressed_byte_count<=compressed_byte_count+diag_bytes;
     token_count<=token_count+total_count;
    end
   end
  end
 end
endmodule

// Two held 128-bit beats; one 32-bit group is retired on every active clock.
// Lookahead preserves early-SOF closure/orphan rejection of the serial path.
module rgb128_quad_stream #(
 parameter integer IMAGE_WIDTH=1920,IMAGE_HEIGHT=1080
)(
 input wire clk,rst_n,i_valid,output wire i_ready,input wire [127:0] i_data,
 input wire i_sof,i_frame_last,input wire [31:0] i_frame_id,
 output wire o_valid,input wire o_ready,output wire [31:0] o_data,
 output wire o_sof,o_last,output wire [31:0] o_frame_id,
 output reg [31:0] error_count
);
 localparam integer TOTAL_BEATS=IMAGE_WIDTH*IMAGE_HEIGHT*3/16;
 reg active,in_frame;reg [127:0] data_q,peek_data;reg [1:0] index;
 reg sof_q,last_q,peek_valid,peek_sof,peek_last;
 reg [31:0] frame_id_q,peek_id,beat_count;
 assign o_valid=active && (index!=3 || last_q || peek_valid);
 assign o_data=data_q[index*32 +:32];
 assign o_sof=o_valid && sof_q && index==0;
 assign o_last=o_valid && index==3 && (last_q || (peek_valid && peek_sof));
 assign o_frame_id=frame_id_q;
 wire tail_fire=o_valid && o_ready && index==3;
 assign i_ready=!peek_valid || tail_fire;
 task load_beat;
  input [127:0] d;input s,l;input [31:0] id;input closing;
  reg [31:0] count;
  begin
   if(s || (in_frame && !closing)) begin
    count=s ? 32'd1 : beat_count+1'b1;
    active<=1;data_q<=d;index<=0;sof_q<=s;
    if(s) frame_id_q<=id;
    in_frame<=1;beat_count<=count;last_q<=l || count>=TOTAL_BEATS;
    if((l && count!=TOTAL_BEATS) || (!l && count>=TOTAL_BEATS))
     error_count<=error_count+1'b1;
   end else begin active<=0;error_count<=error_count+1'b1;end
  end
 endtask
 always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
   active<=0;in_frame<=0;data_q<=0;peek_data<=0;index<=0;
   sof_q<=0;last_q<=0;peek_valid<=0;peek_sof<=0;peek_last<=0;
   frame_id_q<=0;peek_id<=0;beat_count<=0;error_count<=0;
  end else begin
   if(o_valid && o_ready) begin
    if(index==3) begin
     active<=0;index<=0;
     if(o_last) begin
      in_frame<=0;beat_count<=0;
      if(!last_q) error_count<=error_count+1'b1;
     end
     if(peek_valid) begin
      load_beat(peek_data,peek_sof,peek_last,peek_id,o_last);
      peek_valid<=0;
     end
    end else index<=index+1'b1;
   end
   if(!active && peek_valid) begin
    load_beat(peek_data,peek_sof,peek_last,peek_id,1'b0);peek_valid<=0;
   end
   if(i_valid && i_ready) begin
    if(!active && !peek_valid) load_beat(i_data,i_sof,i_frame_last,i_frame_id,1'b0);
    else begin
     peek_valid<=1;peek_data<=i_data;peek_sof<=i_sof;
     peek_last<=i_frame_last;peek_id<=i_frame_id;
    end
   end
  end
 end
endmodule

// Wide byte compactor. Payload batches contain 0..12 bytes; header/footer
// fragments contain up to 16 bytes. Full beats and a short TLAST tail only.
module lz77_quad_packer #(parameter integer PACKET_BEATS=1024)(
 input wire clk,rst_n,i_valid,output wire i_ready,
 input wire [127:0] i_data,input wire [4:0] i_bytes,input wire i_last,
 output reg o_valid,input wire o_ready,output reg [127:0] o_data,
 output reg [15:0] o_keep,output reg o_last
);
 localparam integer PBITS=PACKET_BEATS>1 ? $clog2(PACKET_BEATS):1;
 reg [PBITS-1:0] packet_beats;
 reg [127:0] acc;reg [4:0] acc_bytes;reg end_pending;
 reg [255:0] joined;reg [5:0] joined_bytes;integer b;
 wire room=!o_valid || o_ready;
 assign i_ready=room && !end_pending;
 function [15:0] mask;
  input [5:0] n;
  begin mask=n>=16 ? 16'hffff : ((17'h1<<n)-1'b1);end
 endfunction
 always @* begin
  joined={128'd0,acc};
  for(b=0;b<16;b=b+1)
   if(b<i_bytes) joined[(acc_bytes+b)*8 +:8]=i_data[b*8 +:8];
  joined_bytes=acc_bytes+i_bytes;
 end
 always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
   o_valid<=0;o_data<=0;o_keep<=0;o_last<=0;packet_beats<=0;
   acc<=0;acc_bytes<=0;end_pending<=0;
  end else begin
   if(o_valid && o_ready) begin o_valid<=0;o_last<=0;end
   if(room && end_pending) begin
    o_valid<=1;o_data<=acc;o_keep<=mask(acc_bytes);o_last<=1;
    acc<=0;acc_bytes<=0;end_pending<=0;packet_beats<=0;
   end else if(i_valid && i_ready) begin
    if(joined_bytes>=16 || i_last) begin
     o_valid<=1;o_data<=joined[127:0];o_keep<=mask(joined_bytes);
     o_last<=(i_last && joined_bytes<=16) || packet_beats==PACKET_BEATS-1;
     if((i_last && joined_bytes<=16) || packet_beats==PACKET_BEATS-1)
      packet_beats<=0;
     else packet_beats<=packet_beats+1'b1;
     if(joined_bytes>16) begin
      acc<=joined[255:128];acc_bytes<=joined_bytes-16;end_pending<=i_last;
     end else begin acc<=0;acc_bytes<=0;end
    end else begin acc<=joined[127:0];acc_bytes<=joined_bytes;end
   end
  end
 end
endmodule

module lz77_quad_formatter #(
 parameter integer IMAGE_WIDTH=1920,IMAGE_HEIGHT=1080
)(
 input wire clk,rst_n,i_valid,output wire i_ready,
 input wire [95:0] i_data,input wire [3:0] i_bytes,input wire [2:0] i_tokens,
 input wire [15:0] i_raw,input wire i_sof,i_last,input wire [31:0] i_frame_id,
 output reg o_valid,input wire o_ready,output reg [127:0] o_data,
 output reg [4:0] o_bytes,output reg o_last,
 output reg [31:0] frame_count,error_count
);
 localparam IDLE=0,HEADER=1,PAYLOAD=2,FOOTER=3,CRC_WORD=4;
 reg [2:0] state;
 reg pending_valid,pending_last;reg [95:0] pending_data;
 reg [3:0] pending_bytes;reg [2:0] pending_tokens;
 reg [15:0] pending_raw;reg [31:0] pending_id;
 reg [31:0] raw_count,comp_count,tokens,crc_reg,footer_crc;
// GF(2) XOR equations for 2..12 low-first payload bytes. Independently
// checked against IEEE/zlib by check_quad_crc.py; no CRC polynomial change.
function [31:0] crc_parallel;
 input [31:0] c;input [95:0] d;input [3:0] n;
 begin
  case(n)
   4'd2: begin
    crc_parallel[0]=c[0] ^ c[4] ^ c[6] ^ c[7] ^ c[10] ^ c[16] ^ d[0] ^ d[4] ^ d[6] ^ d[7] ^ d[10];
    crc_parallel[1]=c[1] ^ c[5] ^ c[7] ^ c[8] ^ c[11] ^ c[17] ^ d[1] ^ d[5] ^ d[7] ^ d[8] ^ d[11];
    crc_parallel[2]=c[2] ^ c[6] ^ c[8] ^ c[9] ^ c[12] ^ c[18] ^ d[2] ^ d[6] ^ d[8] ^ d[9] ^ d[12];
    crc_parallel[3]=c[3] ^ c[7] ^ c[9] ^ c[10] ^ c[13] ^ c[19] ^ d[3] ^ d[7] ^ d[9] ^ d[10] ^ d[13];
    crc_parallel[4]=c[4] ^ c[8] ^ c[10] ^ c[11] ^ c[14] ^ c[20] ^ d[4] ^ d[8] ^ d[10] ^ d[11] ^ d[14];
    crc_parallel[5]=c[5] ^ c[9] ^ c[11] ^ c[12] ^ c[15] ^ c[21] ^ d[5] ^ d[9] ^ d[11] ^ d[12] ^ d[15];
    crc_parallel[6]=c[0] ^ c[4] ^ c[7] ^ c[12] ^ c[13] ^ c[22] ^ d[0] ^ d[4] ^ d[7] ^ d[12] ^ d[13];
    crc_parallel[7]=c[1] ^ c[5] ^ c[8] ^ c[13] ^ c[14] ^ c[23] ^ d[1] ^ d[5] ^ d[8] ^ d[13] ^ d[14];
    crc_parallel[8]=c[0] ^ c[2] ^ c[6] ^ c[9] ^ c[14] ^ c[15] ^ c[24] ^ d[0] ^ d[2] ^ d[6] ^ d[9] ^ d[14] ^ d[15];
    crc_parallel[9]=c[1] ^ c[3] ^ c[4] ^ c[6] ^ c[15] ^ c[25] ^ d[1] ^ d[3] ^ d[4] ^ d[6] ^ d[15];
    crc_parallel[10]=c[2] ^ c[5] ^ c[6] ^ c[10] ^ c[26] ^ d[2] ^ d[5] ^ d[6] ^ d[10];
    crc_parallel[11]=c[3] ^ c[6] ^ c[7] ^ c[11] ^ c[27] ^ d[3] ^ d[6] ^ d[7] ^ d[11];
    crc_parallel[12]=c[0] ^ c[4] ^ c[7] ^ c[8] ^ c[12] ^ c[28] ^ d[0] ^ d[4] ^ d[7] ^ d[8] ^ d[12];
    crc_parallel[13]=c[0] ^ c[1] ^ c[5] ^ c[8] ^ c[9] ^ c[13] ^ c[29] ^ d[0] ^ d[1] ^ d[5] ^ d[8] ^ d[9] ^ d[13];
    crc_parallel[14]=c[1] ^ c[2] ^ c[6] ^ c[9] ^ c[10] ^ c[14] ^ c[30] ^ d[1] ^ d[2] ^ d[6] ^ d[9] ^ d[10] ^ d[14];
    crc_parallel[15]=c[2] ^ c[3] ^ c[7] ^ c[10] ^ c[11] ^ c[15] ^ c[31] ^ d[2] ^ d[3] ^ d[7] ^ d[10] ^ d[11] ^ d[15];
