   state<=IDLE;pending_valid<=0;pending_last<=0;pending_data<=0;
   pending_bytes<=0;pending_tokens<=0;pending_raw<=0;pending_id<=0;
   raw_count<=0;comp_count<=0;tokens<=0;crc_reg<=32'hffffffff;
   footer_crc<=0;frame_count<=0;error_count<=0;
  end else begin
   case(state)
    IDLE: if(i_valid && i_ready) begin
     if(!i_sof) error_count<=error_count+1'b1;
     pending_valid<=1;pending_last<=i_last;pending_data<=i_data;
     pending_bytes<=i_bytes;pending_tokens<=i_tokens;pending_raw<=i_raw;
     pending_id<=i_frame_id;raw_count<=0;comp_count<=0;tokens<=0;
     crc_reg<=32'hffffffff;state<=HEADER;
    end
    HEADER: if(o_valid && o_ready) state<=PAYLOAD;
    PAYLOAD: begin
     if(pending_valid && o_ready) begin
      raw_count<=raw_count+pending_raw;comp_count<=comp_count+pending_bytes;
      tokens<=tokens+pending_tokens;crc_reg<=crc_after;
      if(pending_last) begin
       footer_crc<=~crc_after;pending_valid<=0;state<=FOOTER;
      end else if(i_valid && i_ready) begin
       pending_valid<=1;pending_last<=i_last;pending_data<=i_data;
       pending_bytes<=i_bytes;pending_tokens<=i_tokens;pending_raw<=i_raw;
      end else pending_valid<=0;
     end else if(!pending_valid && i_valid && i_ready) begin
      pending_valid<=1;pending_last<=i_last;pending_data<=i_data;
      pending_bytes<=i_bytes;pending_tokens<=i_tokens;pending_raw<=i_raw;
     end
    end
    FOOTER: if(o_valid && o_ready) state<=CRC_WORD;
    CRC_WORD: if(o_valid && o_ready) begin frame_count<=frame_count+1'b1;state<=IDLE;end
    default: state<=IDLE;
   endcase
  end
 end
endmodule
